1	/**
2	 * AuthService — local-only authentication, session, and password management.
3	 *
4	 * Responsibilities:
5	 *   - username/password login and logout
6	 *   - login lockout (5 failed attempts → 15-minute lock)
7	 *   - password validation (min 12 chars, ≥1 digit, ≥1 symbol)
8	 *   - guest trial session (read-only, 30-minute hard expiry)
9	 *   - inactivity auto-lock (10 minutes)
10	 *   - password change with session-key rotation
11	 *   - account deactivation
12	 *   - RBAC role resolution
13	 */
14	
15	import { UserRepository } from '../repositories/implementations/UserRepository.js';
16	import { cryptoService } from './CryptoService.js';
17	import { auditService } from './AuditService.js';
18	import { generateId } from '../utils/idGenerator.js';
19	import { validatePassword, isValidRole } from '../utils/validation.js';
20	import { ROLES, VALIDATION } from '../utils/constants.js';
21	import { cancel, schedule } from '../infrastructure/scheduler/timerManager.js';
22	import {
23	  broadcast,
24	  subscribe,
25	  CHANNEL_NAMES,
26	  EVENT_TYPES,
27	} from '../infrastructure/broadcast/broadcastManager.js';
28	
29	const LOCK_TIMER_KEY = 'auth:auto_lock';
30	const GUEST_TIMER_KEY = 'auth:guest_expiry';
31	const MAX_FAILED_ATTEMPTS = 5;
32	const LOCKOUT_DURATION_MS = 15 * 60_000; // 15 minutes
33	/** Max wrong-password attempts on unlockSession before forcing full logout. */
34	const MAX_UNLOCK_ATTEMPTS = 5;
35	
36	export class AuthService {
37	  constructor() {
38	    this._userRepo = new UserRepository();
39	    /** @type {object | null} Currently active user record. */
40	    this._currentUser = null;
41	    /** @type {boolean} */
42	    this._isLocked = false;
43	    /** @type {boolean} */
44	    this._isGuestSession = false;
45	    /**
46	     * In-memory counter for failed unlockSession attempts.
47	     * Resets on successful unlock or full login.
48	     * Not persisted — physical access resets it (acceptable for local-only app).
49	     * @type {number}
50	     */
51	    this._unlockAttempts = 0;
52	
53	    // Listen for lock events broadcast from other tabs.
54	    subscribe(CHANNEL_NAMES.STATE, (event) => {
55	      if (event.type === EVENT_TYPES.SESSION_LOCKED) {
56	        this._isLocked = true;
57	        cryptoService.clearSessionKey();
58	      } else if (event.type === EVENT_TYPES.SESSION_LOGGED_OUT) {
59	        this._currentUser = null;
60	        this._isLocked = false;
61	        cryptoService.clearSessionKey();
62	      }
63	    });
64	  }
65	
66	  // ── Login / logout ───────────────────────────────────────────────────────────
67	
68	  /**
69	   * Authenticates a user with username and password.
70	   * Derives the session encryption key on success.
71	   * Tracks failed attempts; locks account for 15 minutes after 5 failures.
72	   *
73	   * @param {string} username
74	   * @param {string} password
75	   * @returns {Promise<object>}  The authenticated user record.
76	   * @throws {Error} On invalid credentials, deactivated account, or lockout.
77	   */
78	  async login(username, password) {
79	    const user = await this._userRepo.findByUsername(username);
80	
81	    // All failure paths return the same generic message to prevent enumeration.
82	    if (!user) throw new Error('Invalid credentials.');
83	    if (!user.isActive) throw new Error('Invalid credentials.');
84	
85	    const now = Date.now();
86	    if (user.lockoutUntil && now < user.lockoutUntil) {
87	      throw new Error('Invalid credentials.');
88	    }
89	
90	    const valid = await cryptoService.verifyPassword(password, user.passwordSalt, user.passwordHash);
91	
92	    if (!valid) {
93	      const failedAttempts = (user.failedLoginAttempts ?? 0) + 1;
94	      const lockoutUntil = failedAttempts >= MAX_FAILED_ATTEMPTS
95	        ? Date.now() + LOCKOUT_DURATION_MS
96	        : null;
97	
98	      await this._userRepo.update(user.id, {
99	        ...user,
100	        failedLoginAttempts: failedAttempts,
101	        lockoutUntil,
102	        updatedAt: Date.now(),
103	      });
104	
105	      // Generic error — same message regardless of lockout to prevent enumeration.
106	      throw new Error('Invalid credentials.');
107	    }
108	
109	    // Success: clear failure state.
110	    const freshUser = {
111	      ...user,
112	      failedLoginAttempts: 0,
113	      lockoutUntil: null,
114	      updatedAt: Date.now(),
115	    };
116	    await this._userRepo.update(user.id, freshUser);
117	
118	    // Login does NOT derive the data encryption key. The encryption key is
119	    // derived exclusively from the org passphrase via unlockProtectedData().
120	    // This ensures the login password is never used for data encryption.
121	
122	    this._currentUser = freshUser;
123	    this._isLocked = false;
124	    this._isGuestSession = false;
125	    this._unlockAttempts = 0; // reset on any successful login
126	
127	    this._resetLockTimer();
128	
129	    await auditService.log({
130	      actorId: user.id,
131	      action: 'login',
132	      entityType: 'user',
133	      entityId: user.id,
134	    });
135	
136	    return freshUser;
137	  }
138	
139	  /**
140	   * Logs out the current user and clears all session state.
141	   * @returns {Promise<void>}
142	   */
143	  async logout() {
144	    if (this._currentUser) {
145	      await auditService.log({
146	        actorId: this._currentUser.id,
147	        action: 'logout',
148	        entityType: 'user',
149	        entityId: this._currentUser.id,
150	      });
151	    }
152	
153	    cancel(LOCK_TIMER_KEY);
154	    cancel(GUEST_TIMER_KEY);
155	    cryptoService.clearSessionKey();
156	
157	    this._currentUser = null;
158	    this._isLocked = false;
159	    this._isGuestSession = false;
160	
161	    broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_LOGGED_OUT);
162	  }
163	
164	  // ── Guest session ────────────────────────────────────────────────────────────
165	
166	  /**
167	   * Creates a temporary read-only guest session.
168	   * Hard-expires after 30 minutes and auto-redirects to login.
169	   *
170	   * @param {(reason: string) => void} onExpiry  Called when the guest session expires.
171	   * @returns {{ id: string; role: string; isGuest: true }}
172	   */
173	  async createGuestSession(onExpiry) {
174	    // Attach guest to the root org so they can explore read-only data.
175	    const allUsers = await this._userRepo.findAll();
176	    const adminUser = allUsers.find((u) => u.role === ROLES.ADMINISTRATOR);
177	    const guestOrgId = adminUser?.organizationNodeId ?? null;
178	
179	    const guestUser = {
180	      id: `guest_${Date.now()}`,
181	      username: 'guest',
182	      role: ROLES.GUEST,
183	      organizationNodeId: guestOrgId,
184	      isActive: true,
185	      isGuest: true,
186	      guestExpiresAt: Date.now() + VALIDATION.GUEST_TRIAL_MINUTES * 60_000,
187	    };
188	
189	    this._currentUser = guestUser;
190	    this._isGuestSession = true;
191	
192	    schedule(
193	      GUEST_TIMER_KEY,
194	      async () => {
195	        onExpiry('Guest trial expired after 30 minutes.');
196	        await this.logout();
197	      },
198	      VALIDATION.GUEST_TRIAL_MINUTES * 60_000,
199	    );
200	
201	    return guestUser;
202	  }
203	
204	  // ── Inactivity lock ──────────────────────────────────────────────────────────
205	
206	  /**
207	   * Resets the inactivity auto-lock timer.
208	   * Must be called on every user interaction.
209	   */
210	  resetInactivityTimer() {
211	    if (!this._currentUser || this._isGuestSession) return;
212	    this._resetLockTimer();
213	  }
214	
215	  /** @private */
216	  _resetLockTimer() {
217	    schedule(
218	      LOCK_TIMER_KEY,
219	      () => {
220	        this.lockSession();
221	      },
222	      VALIDATION.AUTO_LOCK_MINUTES * 60_000,
223	    );
224	  }
225	
226	  /**
227	   * Locks the session — encrypted data becomes inaccessible until unlock.
228	   */
229	  lockSession() {
230	    cryptoService.clearSessionKey();
231	    this._isLocked = true;
232	    broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_LOCKED);
233	  }
234	
235	  /**
236	   * Unlocks the session by re-deriving the encryption key.
237	   *
238	   * @param {string} password
239	   * @returns {Promise<boolean>}
240	   */
241	  async unlockSession(password) {
242	    if (!this._currentUser) throw new Error('No active session to unlock.');
243	
244	    const user = await this._userRepo.findById(this._currentUser.id);
245	    if (!user) throw new Error('User record not found.');
246	
247	    const valid = await cryptoService.verifyPassword(password, user.passwordSalt, user.passwordHash);
248	
249	    if (!valid) {
250	      this._unlockAttempts += 1;
251	      if (this._unlockAttempts >= MAX_UNLOCK_ATTEMPTS) {
252	        // Too many wrong attempts — force full logout to prevent brute-force.
253	        await this.logout();
254	        throw new Error(
255	          `Too many failed unlock attempts (${MAX_UNLOCK_ATTEMPTS}). ` +
256	            'Session has been terminated. Please log in again.',
257	        );
258	      }
259	      return false;
260	    }
261	
262	    // Successful unlock — reset counter, clear lock.
263	    // The screen unlock does NOT derive the encryption key. Protected data
264	    // remains inaccessible until unlockProtectedData(orgPassphrase) is called.
265	    this._unlockAttempts = 0;
266	    this._isLocked = false;
267	    this._resetLockTimer();
268	    broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_UNLOCKED);
269	    return true;
270	  }
271	
272	  // ── Account management ───────────────────────────────────────────────────────
273	
274	  /**
275	   * Creates a new user account.
276	   * Requires administrator role.
277	   *
278	   * @param {{ username: string; password: string; role: string; organizationNodeId: string }} params
279	   * @returns {Promise<object>}
280	   */
281	  async createUser({ username, password, role, organizationNodeId }) {
282	    this._assertPermission('administrator');
283	
284	    const pwValidation = validatePassword(password);
285	    if (!pwValidation.valid) throw new Error(pwValidation.errors.join(' '));
286	    if (!isValidRole(role)) throw new Error(`Invalid role: ${role}`);
287	
288	    // Non-admin/non-guest roles require a valid org node assignment.
289	    if (role !== ROLES.ADMINISTRATOR && role !== ROLES.GUEST) {
290	      if (!organizationNodeId) {
291	        throw new Error(`Role '${role}' requires an organizationNodeId.`);
292	      }
293	      const { OrgRepository } = await import('../repositories/implementations/OrgRepository.js');
294	      const orgRepo = new OrgRepository();
295	      const node = await orgRepo.findById(organizationNodeId);
296	      if (!node) {
297	        throw new Error(`Organization node '${organizationNodeId}' not found.`);
298	      }
299	    }
300	
301	    const { hash, salt } = await cryptoService.hashNewPassword(password);
302	
303	    const user = {
304	      id: generateId(),
305	      username,
306	      passwordHash: hash,
307	      passwordSalt: salt,
308	      role,
309	      organizationNodeId,
310	      isActive: true,
311	      isGuest: false,
312	      guestExpiresAt: null,
313	      failedLoginAttempts: 0,
314	      lockoutUntil: null,
315	      createdAt: Date.now(),
316	      updatedAt: Date.now(),
317	    };
318	
319	    await this._userRepo.create(user);
320	    await auditService.log({
321	      actorId: this._currentUser?.id ?? 'system',
322	      action: 'create_user',
323	      entityType: 'user',
324	      entityId: user.id,
325	      metadata: { username, role },
326	    });
327	
328	    return user;
329	  }
330	
331	  /**
332	   * Links two user accounts. Persisted to the linkedAccounts store.
333	   * Prevents duplicates (A-B == B-A) and self-links.
334	   * Requires: ADMINISTRATOR role.
335	   *
336	   * @param {{ userIdA: string; userIdB: string; reason: string }} params
337	   * @returns {Promise<object>}
338	   */
339	  async linkUserAccounts({ userIdA, userIdB, reason }) {
340	    this._assertPermission('administrator');
341	    if (!userIdA || !userIdB) throw new Error('Both user IDs are required.');
342	    if (userIdA === userIdB) throw new Error('Cannot link a user to themselves.');
343	    if (!reason?.trim() || reason.trim().length < 10) throw new Error('Reason must be at least 10 characters.');
344	
345	    const a = await this._userRepo.findById(userIdA);
346	    const b = await this._userRepo.findById(userIdB);
347	    if (!a) throw new Error(`User '${userIdA}' not found.`);
348	    if (!b) throw new Error(`User '${userIdB}' not found.`);
349	
350	    // Duplicate check (A-B == B-A)
351	    const { LinkedAccountRepository } = await import('../repositories/implementations/RiskRepository.js');
352	    const linkRepo = new LinkedAccountRepository();
353	    const existingA = await linkRepo.findAllLinksForUser(userIdA);
354	    const isDuplicate = existingA.some(
355	      (l) => (l.primaryUserId === userIdB || l.linkedUserId === userIdB),
356	    );
357	    if (isDuplicate) throw new Error('These users are already linked.');
358	
359	    const link = {
360	      id: generateId(),
361	      primaryUserId: userIdA,
362	      linkedUserId: userIdB,
363	      evidenceType: 'admin_link',
364	      evidenceDetails: reason,
365	      organizationId: a.organizationNodeId,
366	      createdAt: Date.now(),
367	    };
368	    await linkRepo.create(link);
369	
370	    await auditService.log({
371	      actorId: this._currentUser?.id ?? 'system',
372	      action: 'link_user_accounts',
373	      entityType: 'user',
374	      entityId: userIdA,
375	      metadata: { linkedTo: userIdB, reason },
376	    });
377	
378	    return link;
379	  }
380	
381	  /**
382	   * Returns all account links for a user.
383	   * Requires: ADMINISTRATOR role.
384	   * @param {string} userId
385	   * @returns {Promise<object[]>}
386	   */
387	  async getLinkedAccounts(userId) {
388	    this._assertPermission('administrator');
389	    const { LinkedAccountRepository } = await import('../repositories/implementations/RiskRepository.js');
390	    const linkRepo = new LinkedAccountRepository();
391	    return linkRepo.findAllLinksForUser(userId);
392	  }
393	
394	  /**
395	   * Removes an account link.
396	   * Requires: ADMINISTRATOR role.
397	   * @param {string} linkId
398	   * @returns {Promise<void>}
399	   */
400	  async unlinkAccounts(linkId) {
401	    this._assertPermission('administrator');
402	    const { LinkedAccountRepository } = await import('../repositories/implementations/RiskRepository.js');
403	    const linkRepo = new LinkedAccountRepository();
404	    const link = await linkRepo.findById(linkId);
405	    if (!link) throw new Error(`Link '${linkId}' not found.`);
406	    await linkRepo.delete(linkId);
407	    await auditService.log({
408	      actorId: this._currentUser?.id ?? 'system',
409	      action: 'unlink_user_accounts',
410	      entityType: 'user',
411	      entityId: linkId,
412	    });
413	  }
414	
415	  /**
416	   * Changes a user's login password.
417	   * Password changes do NOT affect the data encryption key — that is derived
418	   * exclusively from the org passphrase, independent of any user's login password.
419	   *
420	   * @param {string} userId
421	   * @param {string} oldPassword
422	   * @param {string} newPassword
423	   * @returns {Promise<void>}
424	   */
425	  async changePassword(userId, oldPassword, newPassword) {
426	    const pwValidation = validatePassword(newPassword);
427	    if (!pwValidation.valid) throw new Error(pwValidation.errors.join(' '));
428	
429	    const user = await this._userRepo.findById(userId);
430	    if (!user) throw new Error('User not found.');
431	
432	    const valid = await cryptoService.verifyPassword(oldPassword, user.passwordSalt, user.passwordHash);
433	    if (!valid) throw new Error('Old password is incorrect.');
434	
435	    const { hash, salt } = await cryptoService.hashNewPassword(newPassword);
436	
437	    await this._userRepo.update(userId, {
438	      ...user,
439	      passwordHash: hash,
440	      passwordSalt: salt,
441	      updatedAt: Date.now(),
442	    });
443	
444	    // Password change does NOT touch the encryption key. The data encryption
445	    // key is derived from the org passphrase, not the login password.
446	
447	    await auditService.log({
448	      actorId: userId,
449	      action: 'change_password',
450	      entityType: 'user',
451	      entityId: userId,
452	    });
453	  }
454	
455	  /**
456	   * Deactivates a user account.
457	   * Requires administrator role.
458	   * @param {string} userId
459	   * @returns {Promise<void>}
460	   */
461	  async deactivateAccount(userId) {
462	    this._assertPermission('administrator');
463	
464	    const user = await this._userRepo.findById(userId);
465	    if (!user) throw new Error('User not found.');
466	
467	    await this._userRepo.update(userId, { ...user, isActive: false, updatedAt: Date.now() });
468	
469	    // Force-logout the deactivated user if they are the current session.
470	    if (this._currentUser?.id === userId) {
471	      await this.logout();
472	    }
473	    // Broadcast so other tabs also invalidate.
474	    broadcast(CHANNEL_NAMES.STATE, EVENT_TYPES.SESSION_LOGGED_OUT);
475	
476	    await auditService.log({
477	      actorId: this._currentUser?.id ?? 'system',
478	      action: 'deactivate_account',
479	      entityType: 'user',
480	      entityId: userId,
481	    });
482	  }
483	
484	  // ── User listing ────────────────────────────────────────────────────────────
485	
486	  /**
487	   * Returns all user accounts.
488	   * Requires: ADMINISTRATOR role.
489	   *
490	   * @returns {Promise<object[]>}
491	   */
492	  async listUsers() {
493	    this._assertPermission('administrator');
494	    return this._userRepo.findAll();
495	  }
496	
497	  // ── State accessors ──────────────────────────────────────────────────────────
498	
499	  /** @returns {object | null} */
500	  getCurrentUser() {
501	    return this._currentUser;
502	  }
503	
504	  /** @returns {boolean} */
505	  isAuthenticated() {
506	    return this._currentUser !== null && !this._isGuestSession;
507	  }
508	
509	  /** @returns {boolean} */
510	  isLocked() {
511	    return this._isLocked;
512	  }
513	
514	  /**
515	   * Throws if the session is locked. Call from mutation paths.
516	   */
517	  requireUnlocked() {
518	    if (this._isLocked) throw new Error('Session is locked. Unlock to perform this action.');
519	  }
520	
521	  /** @returns {boolean} */
522	  isGuest() {
523	    return this._isGuestSession;
524	  }
525	
526	  /**
527	   * Returns true if the current user has the given role or Administrator access.
528	   * @param {string} requiredRole
529	   * @returns {boolean}
530	   */
531	  hasRole(requiredRole) {
532	    if (!this._currentUser) return false;
533	    if (this._currentUser.role === ROLES.ADMINISTRATOR) return true;
534	    return this._currentUser.role === requiredRole;
535	  }
536	
537	  // ── Org passphrase management ────────────────────────────────────────────────
538	
539	  /**
540	   * Sets up or updates the org-level passphrase for protected data encryption.
541	   * Derives the encryption key from orgPassphrase + orgSalt and stores a verifier.
542	   * Requires: ADMINISTRATOR role.
543	   *
544	   * @param {string} orgPassphrase  The new org passphrase.
545	   * @returns {Promise<void>}
546	   */
547	  async setupOrgPassphrase(orgPassphrase) {
548	    this._assertPermission('administrator');
549	    if (!orgPassphrase || orgPassphrase.length < 12) {
550	      throw new Error('Org passphrase must be at least 12 characters.');
551	    }
552	
553	    const user = this._currentUser;
554	    const { config, rootOrgId } = await this._resolveOrgConfig(user);
555	    if (!config) throw new Error('Organization config not found.');
556	
557	    // Hash the passphrase for future verification.
558	    const { hash, salt } = await cryptoService.hashNewPassword(orgPassphrase);
559	
560	    // Update config with passphrase verifier and encryption model flag.
561	    const { AppConfigRepository } = await import('../repositories/implementations/AppConfigRepository.js');
562	    const configRepo = new AppConfigRepository();
563	    await configRepo.update(config.id, {
564	      ...config,
565	      orgPassphraseHash: hash,
566	      orgPassphraseSalt: salt,
567	      encryptionModel: 'passphrase',
568	    });
569	
570	    // Derive and set session key from orgPassphrase + orgEncryptionSalt.
571	    await cryptoService.deriveSessionKey(orgPassphrase, config.orgEncryptionSalt);
572	
573	    await auditService.log({
574	      actorId: user.id,
575	      action: 'setup_org_passphrase',
576	      entityType: 'system',
577	      entityId: rootOrgId,
578	    });
579	  }
580	
581	  /**
582	   * Unlocks protected data using the org passphrase.
583	   * Used when encryption model is 'passphrase' — login/unlock only authenticates
584	   * the user but does not derive the data encryption key.
585	   *
586	   * @param {string} orgPassphrase
587	   * @returns {Promise<boolean>}
588	   */
589	  /**
590	   * Unlocks protected data using the org passphrase.
591	   * This is the ONLY way to derive the data encryption key.
592	   * Login password is never used for data encryption.
593	   *
594	   * @param {string} orgPassphrase
595	   * @returns {Promise<boolean>}
596	   */
597	  async unlockProtectedData(orgPassphrase) {
598	    this._assertPermission('store_manager');
599	
600	    const { config } = await this._resolveOrgConfig(this._currentUser);
601	    if (!config) throw new Error('Organization config not found.');
602	    if (!config.orgPassphraseHash || !config.orgPassphraseSalt) {
603	      throw new Error('Org passphrase not configured. An administrator must set it up first.');
604	    }
605	
606	    const valid = await cryptoService.verifyPassword(
607	      orgPassphrase,
608	      config.orgPassphraseSalt,
609	      config.orgPassphraseHash,
610	    );
611	    if (!valid) return false;
612	
613	    await cryptoService.deriveSessionKey(orgPassphrase, config.orgEncryptionSalt);
614	    return true;
615	  }
616	
617	  /**
618	   * Migrates encrypted records from the old password-derived model to the new
619	   * org-passphrase model. Decrypts all sensitive customer fields with the old
620	   * key and re-encrypts them with the new passphrase-derived key.
621	   * Requires: ADMINISTRATOR role.
622	   *
623	   * @param {string} oldLoginPassword  The admin's login password (old key source).
624	   * @param {string} orgPassphrase     The new org passphrase.
625	   * @returns {Promise<number>}  Number of records migrated.
626	   */
627	  async migrateToOrgPassphrase(oldLoginPassword, orgPassphrase) {
628	    this._assertPermission('administrator');
629	    if (!orgPassphrase || orgPassphrase.length < 12) {
630	      throw new Error('Org passphrase must be at least 12 characters.');
631	    }
632	
633	    const user = this._currentUser;
634	    const { config } = await this._resolveOrgConfig(user);
635	    if (!config) throw new Error('Organization config not found.');
636	    if (config.orgPassphraseHash) {
637	      throw new Error('Already using passphrase model. No migration needed.');
638	    }
639	
640	    // Derive old key (password + org salt).
641	    const oldKey = await cryptoService.deriveKeyRaw(oldLoginPassword, config.orgEncryptionSalt);
642	    // Derive new key (passphrase + org salt).
643	    const newKey = await cryptoService.deriveKeyRaw(orgPassphrase, config.orgEncryptionSalt);
644	
645	    // Re-encrypt all customer sensitive fields.
